#!/bin/bash
# Fetch / rebuild everything this environment needs.  Idempotent.
#
# Estimated total download size: 0 GB (no external data or weights).
# Estimated disk usage: ~25 MB.
#
# This gym has no external downloads: the procedural documents, the public
# pre-trained reader (data/pretrained_reader.pt) and the dev audit
# (data/dev_audit/) are generated by first-party code and committed to git.
# If any of them is missing (e.g. a partial checkout), it is regenerated here
# from its public seed with the same code.  The four hidden test audits live in
# eval/test/ (committed) and are rebuilt only by eval/test/build_test_audit.py.
set -euo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT"
export PYTHONPATH="$ROOT:${PYTHONPATH:-}"
export DOCMIA_THREADS=${DOCMIA_THREADS:-1}
mkdir -p data/downloads
if [ ! -f data/pretrained_reader.pt ] || [ ! -f data/dev_audit/target_stats.json ]; then
  python data/build_public_assets.py
fi
